<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{Download,Upload}from'lucide-vue-next';import{api}from'../api/client';import PageHeader from'../components/PageHeader.vue';import ContentCard from'../components/ContentCard.vue';import FileDropzone from'../components/FileDropzone.vue';const file=ref<File|null>(null),defaultPid=ref(''),loading=ref(false),result=ref<any>(null);async function submit(){if(!file.value)return ElMessage.warning('请选择 Excel 文件');const data=new FormData();data.append('file',file.value);data.append('defaultPid',defaultPid.value);loading.value=true;try{result.value=await api('/api/admin/import',{method:'POST',body:data});ElMessage.success('导入完成')}catch(e){result.value={errors:(e as any).details};ElMessage.error((e as Error).message)}finally{loading.value=false}}</script>
<template><PageHeader title="批量导入导出" description="使用标准 Excel 模板批量维护授权库存，并导出分配记录。"><el-button :icon="Download" tag="a" href="/api/admin/export/template">下载模板</el-button><el-button type="primary" :icon="Download" tag="a" href="/api/admin/export/assigned">导出已分配记录</el-button></PageHeader><ContentCard title="导入授权库存" description="系统会先校验完整文件；PID + DID 重复时跳过并报告，不会覆盖库存。"><div class="import-layout"><div><FileDropzone accept=".xlsx" hint="仅支持 .xlsx 文件，最大 50 MB" @change="file=$event"/><el-form label-position="top"><el-form-item label="默认 PID（文件中没有 PID 列时使用）"><el-input v-model="defaultPid" placeholder="例如 P1001"/></el-form-item><el-button type="primary" :icon="Upload" :loading="loading" :disabled="!file" @click="submit">开始导入</el-button></el-form></div><div class="result-panel"><template v-if="result?.ok"><span>导入结果</span><strong>{{result.inserted}}</strong><p>共 {{result.totalRows}} 行，跳过 {{result.skipped}} 行</p><el-alert v-if="result.conflicts?.length" title="重复记录" type="warning" :description="result.conflicts.join('、')" show-icon/></template><template v-else-if="result?.errors"><span>校验未通过</span><ul><li v-for="error in result.errors" :key="error">{{error}}</li></ul></template><template v-else><span>等待导入</span><p>导入完成后将在这里显示新增数量和冲突明细。</p></template></div></div></ContentCard></template>
